using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Collections;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Automation;using Gunt.ControlCenter.Models;using Gunt.ControlCenter.Services;
namespace Gunt.ControlCenter.Views {
 public sealed partial class MainWindow {
  ListBox developerProjects,rootList,sessionList,ruleList,commandList;TextBox developerSearch;TextBlock projectDetails,environmentDetails,sessionDetails;CheckBox showHidden;ComboBox scanDepth;int projectGeneration;string lastDeveloperSelection;
  bool RenderDeveloperPage(string id){if(id=="developer-setup"){BuildDeveloperSetup();return true;}if(id=="wsl-environments"){BuildWslEnvironment();return true;}if(id=="development-sessions"){BuildDevelopmentSessions();return true;}if(id=="commands"){BuildCommandsPage();return true;}if(id=="smart-automation"){BuildSmartAutomation();return true;}return false;}
  ListBox DataList(string name,double height=180){var list=new ListBox{Height=height,Background=Secondary,Foreground=TextColor,BorderBrush=Line,Margin=new Thickness(0,4,0,10)};AutomationProperties.SetName(list,name);return list;}
  TextBox EditBox(Panel panel,string label,string value){panel.Children.Add(new TextBlock{Text=label,Margin=new Thickness(0,5,0,4),Foreground=Muted});var box=new TextBox{Text=value??"",Margin=new Thickness(0,0,0,7)};AutomationProperties.SetName(box,label);panel.Children.Add(box);return box;}
  ComboBox Choice(Panel panel,string label,IEnumerable<ChoiceOption> options,string value){panel.Children.Add(new TextBlock{Text=label,Foreground=Muted,Margin=new Thickness(0,5,0,4)});var combo=new ComboBox{ItemsSource=options.ToArray(),DisplayMemberPath="Value",SelectedValuePath="Key",SelectedValue=value,Margin=new Thickness(0,0,0,8)};AutomationProperties.SetName(combo,label);panel.Children.Add(combo);return combo;}
  Window EditorWindow(string title,out StackPanel panel){var w=new Window{Title=title,Owner=this,Width=620,Height=650,Background=Surface,Foreground=TextColor,FontFamily=FontFamily,FontSize=14,WindowStartupLocation=WindowStartupLocation.CenterOwner};w.MaxHeight=Math.Max(360,ActualHeight-20);w.Resources.MergedDictionaries.Add(Resources);w.SourceInitialized+=delegate{int dark=1;DwmSetWindowAttribute(new System.Windows.Interop.WindowInteropHelper(w).Handle,20,ref dark,4);};panel=new StackPanel{Margin=new Thickness(18)};w.Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};return w;}
  void SaveEditor(Window w,Panel panel,Action save){bool saved=false;string initial=null;Func<string> snapshot=()=>String.Join("|",panel.Children.Cast<UIElement>().Select(x=>x is TextBox?((TextBox)x).Text:x is ComboBox?Convert.ToString(((ComboBox)x).SelectedValue):x is CheckBox?Convert.ToString(((CheckBox)x).IsChecked):x is ListBox?String.Join(";",((ListBox)x).Items.Cast<object>().Select(Convert.ToString)):""));var error=new TextBlock{Foreground=Accent,TextWrapping=TextWrapping.Wrap};panel.Children.Add(error);var buttons=new WrapPanel();panel.Children.Add(buttons);var b=new Button{Content="저장",IsDefault=true};b.Click+=delegate{try{save();saved=true;w.DialogResult=true;}catch(Exception e){error.Text=e.Message;}};buttons.Children.Add(b);buttons.Children.Add(new Button{Content="취소",IsCancel=true});w.Loaded+=delegate{initial=snapshot();};w.Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){if(saved||initial==null||snapshot()==initial)return;var choice=MessageBox.Show(w,"저장하지 않은 편집이 있습니다.\n예: 저장 후 닫기 · 아니요: 버리기 · 취소: 계속 편집","미저장 개발 설정",MessageBoxButton.YesNoCancel,MessageBoxImage.Question,MessageBoxResult.Cancel);if(choice==MessageBoxResult.Cancel)e.Cancel=true;else if(choice==MessageBoxResult.Yes){e.Cancel=true;w.Dispatcher.BeginInvoke((Action)(()=>b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent))));}};}
  string BrowseFolder(){using(var d=new System.Windows.Forms.FolderBrowserDialog{ShowNewFolderButton=false})return d.ShowDialog()==System.Windows.Forms.DialogResult.OK?d.SelectedPath:null;}
  ProjectEntry DeveloperSelection(){return Dispatcher.Invoke(new Func<ProjectEntry>(()=>{var p=developerProjects==null?null:developerProjects.SelectedItem as ProjectEntry;if(p==null)throw new ArgumentException("프로젝트를 먼저 선택하세요.");return p;}));}
  void BuildDeveloperSetup(){lastDeveloperSelection=null;Text("프로젝트를 선택하면 이후 개발 도구와 빠른 패널에서도 같은 폴더를 사용합니다.",true);var d=vm.Service.Developer();rootList=DataList("등록한 프로젝트 루트",d.Roots.Count==0?26:65);rootList.ItemsSource=d.Roots.ToArray();content.Children.Add(rootList);var a=Actions();Action(a,"프로젝트 루트 추가",()=>{string path=Dispatcher.Invoke(new Func<string>(BrowseFolder));if(path==null)return "폴더 선택을 취소했습니다.";vm.Service.RegisterRoot(path);Dispatcher.Invoke((Action)(()=>Show("developer-setup")));return "실제 폴더를 탐색 루트로 등록했습니다.";});Action(a,"루트 등록 해제",()=>{string path=Dispatcher.Invoke(new Func<string>(()=>rootList.SelectedItem as string));if(path==null)throw new ArgumentException("해제할 루트를 선택하세요.");vm.Service.RemoveRoot(path);Dispatcher.Invoke((Action)(()=>Show("developer-setup")));return "루트 등록만 해제했습니다. 폴더·프로젝트 등록은 보존했습니다.";});Action(a,"전역 개발 기본값",()=>{Dispatcher.Invoke((Action)(()=>EditDeveloperPreferences(null)));return "개발 기본값 편집을 마쳤습니다.";});
   var options=new WrapPanel{Margin=new Thickness(0,0,0,10)};content.Children.Add(options);options.Children.Add(new TextBlock{Text="탐색 깊이",VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,8,0)});scanDepth=new ComboBox{ItemsSource=new[]{1,2,3,4,5},SelectedItem=d.ScanDepth,Width=70,Margin=new Thickness(0,0,14,0)};showHidden=new CheckBox{Content="숨김 폴더 표시",IsChecked=d.ShowHidden,Foreground=TextColor,VerticalAlignment=VerticalAlignment.Center};options.Children.Add(scanDepth);options.Children.Add(showHidden);
   developerSearch=new TextBox{Margin=new Thickness(0,0,0,8),ToolTip="이름 또는 전체 경로 검색"};AutomationProperties.SetName(developerSearch,"개발 프로젝트 검색");content.Children.Add(developerSearch);
   a=Actions();Action(a,"다시 탐색",()=>{int depth=Dispatcher.Invoke(new Func<int>(()=>Convert.ToInt32(scanDepth.SelectedItem)));bool hidden=Dispatcher.Invoke(new Func<bool>(()=>showHidden.IsChecked==true));var settings=vm.Service.Developer();settings.ScanDepth=depth;settings.ShowHidden=hidden;vm.Service.SaveDeveloper(settings);var projects=vm.Service.DiscoverProjects();Dispatcher.Invoke((Action)(()=>SetDeveloperProjects(projects)));return "직접 하위 폴더부터 제한 탐색했습니다. 발견 "+projects.Length+"개. 재분석 지점은 건너뜁니다.";});Action(a,"최근 사용 순",()=>{var recent=vm.Service.State("project-recent");Dispatcher.Invoke((Action)(()=>SetDeveloperProjects(developerItems.OrderByDescending(p=>DesktopService.S(recent,p.Id)).ToArray())));return "최근 실행 요청 순으로 정렬했습니다.";});Action(a,"이름순",()=>{Dispatcher.Invoke((Action)(()=>SetDeveloperProjects(developerItems.OrderBy(p=>p.Name).ToArray())));return "이름순으로 정렬했습니다.";});
   var split=new Grid();split.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(0.46,GridUnitType.Star)});split.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(0.54,GridUnitType.Star)});content.Children.Add(split);developerProjects=DataList("개발 프로젝트 목록",140);developerProjects.Margin=new Thickness(0,0,16,10);split.Children.Add(developerProjects);projectDetails=new TextBlock{Text="프로젝트를 선택하세요.",Foreground=Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,0)};Grid.SetColumn(projectDetails,1);split.Children.Add(projectDetails);developerProjects.SelectionChanged+=delegate{DeveloperProjectChanged();};developerSearch.TextChanged+=delegate{FilterDeveloperProjects();};
   a=Actions();foreach(var pair in new[]{new[]{"기본 AI CLI","ai"},new[]{"WSL + Codex","codex"},new[]{"WSL + OpenCode","opencode"},new[]{"VS Code","ide"},new[]{"폴더","folder"},new[]{"WSL 셸","wsl"},new[]{"CMD","cmd"},new[]{"PowerShell","powershell"},new[]{"Windows Terminal","terminal"},new[]{"GitHub","repository"}}){string action=pair[1];Action(a,pair[0],()=>vm.Service.LaunchDeveloper(DeveloperSelection(),action));}a=Actions();Action(a,"프로젝트 개발 설정",()=>{var p=DeveloperSelection();Dispatcher.Invoke((Action)(()=>EditDeveloperPreferences(p)));return "프로젝트별 개발 설정을 편집했습니다.";});Action(a,"즐겨찾기 전환",()=>{var p=DeveloperSelection();p.Pinned=!p.Pinned;vm.Service.SaveProject(p);Dispatcher.Invoke((Action)(()=>RefreshDeveloperDetails(p)));return "즐겨찾기를 저장했습니다.";});PageButton(a,"개발 세션","development-sessions");PageButton(a,"WSL 환경 확인","wsl-environments");Action(a,"Git 상태 새로고침",()=>{var p=DeveloperSelection();var info=vm.Service.GitStatus(p,true);Dispatcher.Invoke((Action)(()=>ShowProjectInfo(p,info)));return "읽기 전용 Git 상태를 갱신했습니다.";});foreach(var tool in d.Tools){var t=tool;Action(a,t.Name,()=>vm.Service.LaunchDeveloper(DeveloperSelection(),"tool:"+t.Id));}Action(a,"개발 도구 등록",()=>{Dispatcher.Invoke((Action)EditDeveloperTool);return "추가 개발 도구 편집을 마쳤습니다.";});SetDeveloperProjects(vm.Service.Projects());}
  ProjectEntry[] developerItems=new ProjectEntry[0];
  void SetDeveloperProjects(ProjectEntry[] projects){developerItems=projects;FilterDeveloperProjects();}
  void FilterDeveloperProjects(){if(developerProjects==null)return;string query=developerSearch.Text;developerProjects.ItemsSource=developerItems.Where(p=>(p.Name+" "+p.Directory).IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0).ToArray();string active=vm.Service.Developer().SelectedProjectId;developerProjects.SelectedItem=developerProjects.Items.Cast<ProjectEntry>().FirstOrDefault(p=>p.Id==active);if(developerProjects.Items.Count==0)projectDetails.Text="등록한 프로젝트가 없습니다. 루트를 추가해 다시 탐색하거나 프로젝트 페이지에서 실제 폴더를 등록하세요.";}
  void DeveloperProjectChanged(){var p=developerProjects.SelectedItem as ProjectEntry;if(p==null)return;if(p.Id==lastDeveloperSelection)return;lastDeveloperSelection=p.Id;if(!Directory.Exists(p.Directory)){projectDetails.Text=p.Name+"\n"+p.Directory+"\n폴더가 없습니다. 프로젝트 페이지에서 경로를 복구하세요.";return;}p=vm.Service.RegisterDiscovered(p);vm.Service.SelectProject(p.Id);RefreshDeveloperDetails(p);int generation=++projectGeneration;Task.Factory.StartNew(()=>vm.Service.GitStatus(p)).ContinueWith(t=>Dispatcher.BeginInvoke((Action)delegate{if(generation!=projectGeneration||page!="developer-setup")return;if(t.IsFaulted)projectDetails.Text+="\nGit 확인 불가: "+t.Exception.GetBaseException().Message;else ShowProjectInfo(p,t.Result);}));}
  void RefreshDeveloperDetails(ProjectEntry p){projectDetails.Text=p.Name+"\n"+p.Directory+"\n"+(Directory.Exists(p.Directory)?vm.Service.ProjectType(p.Directory):"경로 없음")+"\n즐겨찾기: "+(p.Pinned?"사용":"해제")+"\n최근 실행: "+DesktopService.S(vm.Service.State("project-recent"),p.Id,"기록 없음")+"\n개발 설정: "+(p.Developer==null?"전역 기본값 상속":"프로젝트 지정값 + 전역 기본값");var all=vm.Service.State("project-developer-recent");if(all.ContainsKey(p.Id)){var recent=vm.Service.Json.Deserialize<Dictionary<string,object>>(vm.Service.Json.Serialize(all[p.Id]));projectDetails.Text+="\n최근 AI CLI: "+DesktopService.S(recent,"Cli","기록 없음")+" · "+DesktopService.S(recent,"Distribution")+"\n최근 세션: "+DesktopService.S(recent,"Preset","기록 없음");}}
  void ShowProjectInfo(ProjectEntry p,ProjectInfo info){RefreshDeveloperDetails(p);projectDetails.Text+="\n"+(String.IsNullOrEmpty(info.Repository)?"Git 저장소 확인 불가":("분기: "+info.Branch+"\n수정 "+info.Modified+" · 미추적 "+info.Untracked+"\n"+info.Repository));if(!String.IsNullOrEmpty(info.Error)){RefreshDeveloperDetails(p);projectDetails.Text+="\nGit 상태 확인 불가: "+info.Error;}}
  void EditDeveloperPreferences(ProjectEntry project){StackPanel panel;bool global=project==null;var w=EditorWindow(global?"전역 개발 기본값":"프로젝트 개발 설정",out panel);var data=global?vm.Service.Developer().Defaults:(project.Developer??new DeveloperPreferences());var inherited=vm.Service.Developer().Defaults;var fields=new Dictionary<string,ComboBox>();var dists=vm.Service.State("wsl-environments");var installed=dists.ContainsKey("Distributions")?((IEnumerable)dists["Distributions"]).Cast<object>().Select(Convert.ToString).ToArray():new string[0];foreach(string key in new[]{"TerminalHost","WslDistribution","DefaultAiCli","Editor","SessionPreset","WorkspaceProfile"}){var property=typeof(DeveloperPreferences).GetProperty(key);string value=property.GetValue(data,null) as string;string[] choices=key=="TerminalHost"?new[]{"windows-terminal","cmd"}:key=="DefaultAiCli"?new[]{"codex","opencode"}:key=="Editor"?new[]{"vscode"}:key=="WslDistribution"?installed:key=="WorkspaceProfile"?vm.Service.Profiles().Select(x=>x.Id).ToArray():vm.Service.Sessions().Presets.Select(x=>x.Id).ToArray();var options=new List<ChoiceOption>{new ChoiceOption("",global?"선택 안 함":"상속: "+Convert.ToString(property.GetValue(inherited,null)))};options.AddRange(choices.Concat(new[]{value}).Where(x=>!String.IsNullOrEmpty(x)).Distinct().Select(x=>new ChoiceOption(x,x)));fields[key]=Choice(panel,PreferenceLabel(key),options,value??"");}var user=EditBox(panel,"WSL 일반 계정 (빈 값: 등록 기본 계정 또는 유일한 일반 계정)",data.WslUser);var codex=EditBox(panel,"Codex 실행 이름 또는 Linux 경로",data.CodexExecutable);var opencode=EditBox(panel,"OpenCode 실행 이름 또는 Linux 경로",data.OpenCodeExecutable);panel.Children.Add(new TextBlock{Text="배포판 목록은 WSL 환경 페이지의 새로고침으로 갱신합니다. 빈 프로젝트 설정은 전역 값을 상속합니다.",Foreground=Muted,TextWrapping=TextWrapping.Wrap});SaveEditor(w,panel,()=>{var prefs=new DeveloperPreferences();foreach(var pair in fields)typeof(DeveloperPreferences).GetProperty(pair.Key).SetValue(prefs,Convert.ToString(pair.Value.SelectedValue),null);prefs.WslUser=user.Text.Trim();prefs.CodexExecutable=codex.Text.Trim();prefs.OpenCodeExecutable=opencode.Text.Trim();vm.Service.ValidatePreferences(prefs);if(global){var d=vm.Service.Developer();d.Defaults=prefs;vm.Service.SaveDeveloper(d);}else{project.Developer=prefs;vm.Service.SaveProject(project);}});if(!global){var reset=new Button{Content="프로젝트 지정값 모두 상속으로"};reset.Click+=delegate{foreach(var combo in fields.Values)combo.SelectedValue="";user.Text="";codex.Text="";opencode.Text="";};panel.Children.Add(reset);}w.ShowDialog();}
  static string PreferenceLabel(string key){return new Dictionary<string,string>{{"TerminalHost","터미널 호스트"},{"WslDistribution","WSL 배포판"},{"DefaultAiCli","기본 AI CLI"},{"Editor","편집기"},{"SessionPreset","기본 개발 세션"},{"WorkspaceProfile","작업공간 프로필"}}[key];}
  void EditDeveloperTool(){StackPanel panel;var w=EditorWindow("개발 도구 등록",out panel);var name=EditBox(panel,"도구 이름","");var path=EditBox(panel,"실행 파일 (.exe)","");var choose=new Button{Content="실행 파일 선택"};choose.Click+=delegate{var dialog=new Microsoft.Win32.OpenFileDialog{Filter="실행 파일|*.exe"};if(dialog.ShowDialog(w)==true)path.Text=dialog.FileName;};panel.Children.Add(choose);SaveEditor(w,panel,()=>{var d=vm.Service.Developer();d.Tools.Add(new DeveloperTool{Id="tool-"+Guid.NewGuid().ToString("N"),Name=name.Text.Trim(),Executable=path.Text.Trim()});vm.Service.SaveDeveloper(d);});w.ShowDialog();}
  void BuildWslEnvironment(){Text("정상 Linux 사용자 환경에서만 도구를 확인합니다. 설치·배포판 생성·셸 설정 변경은 하지 않습니다.",true);environmentDetails=new TextBlock{Text="새로고침을 눌러 설치된 배포판을 읽으세요.",Foreground=Muted,TextWrapping=TextWrapping.Wrap};content.Children.Add(environmentDetails);var list=new ComboBox{Margin=new Thickness(0,10,0,10)};AutomationProperties.SetName(list,"WSL 배포판 선택");content.Children.Add(list);var a=Actions();Action(a,"배포판 새로고침",()=>{var names=vm.Service.Distributions();GuntConfiguration.Atomic(root,Path.Combine(root,"state","wsl-environments.json"),vm.Service.Json.Serialize(new {Distributions=names,Time=DateTimeOffset.Now.ToString("o")}),false);Dispatcher.Invoke((Action)(()=>{list.ItemsSource=names;if(names.Length>0)list.SelectedIndex=0;environmentDetails.Text=names.Length+"개 배포판을 찾았습니다.";}));return "배포판 목록을 갱신했습니다.";});Action(a,"선택 환경 도구 확인",()=>{string dist=Dispatcher.Invoke(new Func<string>(()=>list.SelectedItem as string));if(String.IsNullOrEmpty(dist))throw new ArgumentException("배포판을 선택하세요.");var tools=vm.Service.EnvironmentTools(dist);Dispatcher.Invoke((Action)(()=>environmentDetails.Text=dist+"\n"+String.Join("\n",tools.Select(x=>x.ToString()))));return "선택한 WSL의 Git·Node.js·Python·Codex·OpenCode를 확인했습니다.";});Action(a,"선택 배포판을 전역 기본값으로",()=>{string dist=Dispatcher.Invoke(new Func<string>(()=>list.SelectedItem as string));if(String.IsNullOrEmpty(dist))throw new ArgumentException("배포판을 선택하세요.");var d=vm.Service.Developer();d.Defaults.WslDistribution=dist;vm.Service.SaveDeveloper(d);return "전역 WSL 배포판을 저장했습니다. 프로젝트 지정값은 유지합니다.";});}
 }
